package org.kanger;
import java.util.*;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextWitnessResultTransport.*;
final class ContextSignedWitnessGroupedMatrix {
 static int checks;static final int WORK=64000000;
 static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
 static ContextUniversalGroupedLocalRounds.Limits local(int passes,int work){return new ContextUniversalGroupedLocalRounds.Limits(passes,16,512,512,256,16,65536,work);}
 static final class Fixture {
  final ContextSignedWitnessContinuationScope.Receipt scope;final Snapshot b;final boolean trusted;
  Fixture(boolean trusted,boolean reverse)throws Exception{this.trusted=trusted;Snapshot x=ContextSignedWitnessReceiverMatrix.bind(true,"!anchor(1); !@u p(u);"),a=ContextSignedWitnessReceiverMatrix.bind(false,"!@x p(x)&&b(x)->r(x); !$z hidden(z)&&~blocked(z);" );b=ContextSignedWitnessReceiverMatrix.bind(false,"!b(1);");List<Snapshot> members=reverse?Arrays.asList(b,a):Arrays.asList(a,b);List<Snapshot> fs=trusted?Collections.singletonList(ContextProductionNativeBinding.trusted("signed-grouped",members,WORK)):members;ContextSignedWitnessFrameAudit.Receipt seeds=ContextSignedWitnessReceiverMatrix.frame(x,fs);ContextUniversalFrozenBranch.Limits limits=ContextSignedWitnessReceiverMatrix.limits(16,WORK);ContextSignedWitnessInitialEntry.Result initial=ContextSignedWitnessInitialEntry.assemble(seeds,64,limits,WORK,64);require(initial.status==ContextSignedWitnessInitialEntry.Status.READY,initial.reason);ContextSignedWitnessInitialEntry.Receipt receipt=ContextSignedWitnessInitialEntry.inspect(initial.entry,seeds,64,limits,WORK,64);scope=ContextSignedWitnessNextMatrix.scope(receipt,seeds,limits);}
 }
 static int depth(ContextUniversalFrozenConstraints.Result r){return r.proofs.stream().filter(p->p.clause!=null&&p.clause.literals.size()==1&&p.clause.variables.isEmpty()&&p.clause.literals.get(0).predicate.equals("r")&&p.clause.literals.get(0).positive&&p.support.sources.size()==3).mapToInt(p->p.support.depth).min().orElse(Integer.MAX_VALUE);}
 static ContextSignedWitnessNextReceiver.Result grouped(Fixture f,ContextUniversalGroupedLocalRounds.Limits l){ContextSignedWitnessNextReceiver.Result r=ContextSignedWitnessNextReceiver.runGrouped(f.scope,64,f.scope.limits,l,WORK,64);require(r.status==ContextSignedWitnessNextReceiver.Status.CHECKED,r.phase+": "+r.reason);ContextSignedWitnessNextReceiver.checkGrouped(r,f.scope,64,f.scope.limits,l,WORK,1);require(r.certificates.keySet().equals(r.checks.keySet())&&r.checks.size()==(f.trusted?2:3),"ALL supplied cuts have actual local certificates before output");return r;}
 static void positive()throws Exception{
  for(boolean trusted:new boolean[]{false,true})for(boolean reverse:new boolean[]{false,true}){Fixture f=new Fixture(trusted,reverse);ContextUniversalGroupedLocalRounds.Limits l=local(8,WORK);ContextSignedWitnessNextReceiver.Result r=grouped(f,l);for(Cut cut:r.checks.keySet()){ContextUniversalGroupedLocalRounds.Certificate c=r.certificates.get(cut);require(c.initial==r.base.checks.get(cut)&&c.output==r.checks.get(cut)&&c.limits==l&&c.terminal.base==c.output,"exact ordinary base, stable output, policy and fresh terminal owner");require(c.output.input.signedContinuation==f.scope&&c.output.common==f.scope.current().packet&&c.output.exchange==f.scope.units()&&c.output.compounds==f.scope.compounds(),"local completion never changes immutable signed incoming frame");}
   if(!trusted){ContextUniversalGroupedLocalRounds.Certificate c=r.certificates.get(Cut.of(f.b));require(depth(c.output)<depth(c.initial)&&depth(c.output)==1,"same THREE-Source conclusion improved by grouped parallel proof to depth1");require(c.history.size()>=2&&c.history.get(0).changed&&!c.history.get(c.history.size()-1).changed,"grade-only progress needs another local pass before certification");require(!ContextUniversalGroupedLocalRounds.sameContents(c.initial,c.output,ContextGroundProductionRounds.budget(WORK)),"complete Source/grade comparison detects improvement");}
   ContextSignedWitnessSuccessorBarrier.Result barrier=ContextSignedWitnessSuccessorBarrier.run(r,f.scope,64,f.scope.limits,WORK,64);require(barrier.merged,barrier.phase+": "+barrier.reason);for(Map.Entry<Cut,ConstraintTransfer> e:barrier.barrier.branches.entrySet())require(e.getValue().certificate==r.certificates.get(e.getKey())&&e.getValue().bindings!=null,"certified transport retains actual local output and binding receipt");ContextSignedWitnessSuccessorBarrierAudit.inspect(barrier,r,f.scope,64,f.scope.limits,WORK,1);require(true,"independent barrier audit accepts certified grouped products");}
  Fixture f=new Fixture(false,false);ContextUniversalGroupedLocalRounds.Limits l=local(8,WORK);ContextSignedWitnessRounds.Result advanced=ContextSignedWitnessRounds.runGrouped(f.scope,64,f.scope.limits,l,1,WORK,64);require(advanced.status==ContextSignedWitnessRounds.Status.ADVANCED,advanced.phase+": "+advanced.reason);require(advanced.localLimits==l&&advanced.history.get(0).checks.localLimits==l&&advanced.output.generation==2,"explicit grouped mode retained through controller and child lineage");require(advanced.history.get(0).changes.common&&advanced.history.get(0).changes.privatePools&&advanced.history.get(0).changes.any(),"common and private new proof inventories both participate in stopping data");ContextSignedWitnessRounds.Receipt audit=ContextSignedWitnessRounds.inspectGrouped(advanced,f.scope,64,f.scope.limits,l,1,WORK,1);require(audit.result==advanced,"direct grouped full-history audit at capacity1");
  System.out.println("SIGNED_WITNESS_GROUPED orders=4 gradeOnlyDepthImprovement=true wholeLocalManifest=true allCutsBeforeResult=true certifiedProductsAndLineage=true explicitControllerMode=true noGlobalStable=true");
 }
 interface Attempt{void run()throws Exception;}
 static void reject(Attempt a,String why)throws Exception{boolean failed=false;try{a.run();}catch(Exception expected){failed=true;}require(failed,why);}
 static void incomplete(ContextSignedWitnessNextReceiver.Result r,String why){require(r.status==ContextSignedWitnessNextReceiver.Status.INCOMPLETE&&r.scope==null&&r.checks.isEmpty()&&r.certificates.isEmpty()&&r.base==null,why+": no certificate or check prefix");}
 static void boundaries()throws Exception{
  Fixture f=new Fixture(false,false);ContextUniversalGroupedLocalRounds.Limits l=local(8,WORK);incomplete(ContextSignedWitnessNextReceiver.runGrouped(f.scope,64,f.scope.limits,local(1,WORK),WORK,64),"progress without final unchanged local pass");incomplete(ContextSignedWitnessNextReceiver.runGrouped(f.scope,64,f.scope.limits,local(8,1),WORK,64),"local work budget");incomplete(ContextSignedWitnessNextReceiver.runGrouped(f.scope,64,f.scope.limits,l,1,64),"fresh historical audit budget");ContextUniversalGroupedLocalRounds.Limits mismatch=new ContextUniversalGroupedLocalRounds.Limits(8,15,512,512,256,16,65536,WORK);incomplete(ContextSignedWitnessNextReceiver.runGrouped(f.scope,64,f.scope.limits,mismatch,WORK,64),"local/kernel round mismatch");
  ContextSignedWitnessNextReceiver.Result r=grouped(f,l);reject(()->ContextSignedWitnessNextReceiver.checkGrouped(r,f.scope,64,f.scope.limits,local(8,WORK),WORK,64),"equal-valued different local policy is not request owner");reject(()->ContextSignedWitnessNextReceiver.checkGrouped(r,f.scope,64,f.scope.limits,l,1,64),"cannot reuse historical certificate audit work");
  Object old=ContextSignedWitnessBarrierMatrix.replace(r,"certificates",Collections.emptyMap());reject(()->ContextSignedWitnessNextReceiver.check(r,f.scope,64,f.scope.limits,WORK),"missing cut certificates cannot retain ordinary receiver authority");ContextSignedWitnessBarrierMatrix.replace(r,"certificates",old);old=ContextSignedWitnessBarrierMatrix.replace(r,"checks",r.base.checks);reject(()->ContextSignedWitnessNextReceiver.check(r,f.scope,64,f.scope.limits,WORK),"ordinary output cannot replace stable local outputs");ContextSignedWitnessBarrierMatrix.replace(r,"checks",old);
  ContextUniversalGroupedLocalRounds.Certificate c=r.certificates.get(Cut.of(f.b));old=ContextSignedWitnessBarrierMatrix.replace(c,"terminal",c.history.get(0).candidates);reject(()->ContextSignedWitnessNextReceiver.check(r,f.scope,64,f.scope.limits,WORK),"stale terminal scan cannot prove local stability");ContextSignedWitnessBarrierMatrix.replace(c,"terminal",old);ContextSignedWitnessNextReceiver.check(r,f.scope,64,f.scope.limits,WORK);require(true,"restored complete local certificates pass fresh audit");
  ContextSignedWitnessSuccessorBarrier.Result b=ContextSignedWitnessSuccessorBarrier.run(r,f.scope,64,f.scope.limits,WORK,64);require(b.merged,b.reason);ConstraintTransfer plain=ContextWitnessResultTransport.transferConstraintsPrivate(c.output,c.output.pool,16,WORK);require(plain.transferred,plain.reason);Map<Cut,ConstraintTransfer> bad=new LinkedHashMap<>(b.barrier.branches);bad.put(Cut.of(f.b),plain);ConstraintBarrier refused=ContextWitnessResultTransport.mergeSignedWitnessSuccessor(r,bad,WORK);require(!refused.merged&&refused.packet==null&&refused.branches.isEmpty(),"genuine ordinary transfer lacks actual grouped certificate/binding authority");
  ContextSignedWitnessRounds.Result advanced=ContextSignedWitnessRounds.runGrouped(f.scope,64,f.scope.limits,l,1,WORK,64);require(advanced.status==ContextSignedWitnessRounds.Status.ADVANCED,advanced.reason);Object flag=ContextSignedWitnessBarrierMatrix.replace(advanced.history.get(0).changes,"common",false);reject(()->ContextSignedWitnessRounds.inspectGrouped(advanced,f.scope,64,f.scope.limits,l,1,WORK,64),"false common Source-grade change flag rejected");ContextSignedWitnessBarrierMatrix.replace(advanced.history.get(0).changes,"common",flag);reject(()->ContextSignedWitnessRounds.inspect(advanced,f.scope,64,f.scope.limits,1,WORK,64),"ordinary controller audit cannot silently change request mode");reject(()->ContextSignedWitnessRounds.inspectGrouped(advanced,f.scope,64,f.scope.limits,local(8,WORK),1,WORK,64),"controller grouped policy bound exactly");
  System.out.println("SIGNED_WITNESS_GROUPED_BOUNDARIES incompleteLocalPassBudgetPolicyNoPrefixes=true lostCertificatesWrongOutputStaleTerminalRejected=true ordinaryTransferCannotClaimGroupedAuthority=true modeExact=true noAdmission=true");
 }
}
